 24→
 25→export const loader = async ({ request }: LoaderFunctionArgs) => {
 26→  const { session, admin } = await authenticate.admin(request);
 27→  const shop = session.shop;
 28→
 29→  const zipCodes = await db.zipCode.findMany({ where: { shop } });
 30→  const [deliveryRulesCount, waitlistCount, subscription] = await Promise.all([
 31→    db.deliveryRule.count({ where: { shop } }),
 32→    db.waitlistEntry.count({ where: { shop } }),
 33→    getShopSubscription(shop),
 34→  ]);
 35→
 36→  const stats = {
 37→    total: zipCodes.length,
 38→    allowed: zipCodes.filter((z) => z.type === "allowed").length,
 39→    blocked: zipCodes.filter((z) => z.type === "blocked").length,
 40→    deliveryRules: deliveryRulesCount,
 41→    waitlist: waitlistCount,
 42→  };
 43→
 44→  // Detect whether the App Embed is enabled in the active theme (GraphQL)
 45→  let appEmbedEnabled = false;
 46→  let activeThemeName: string | null = null;
 47→  let themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
 48→  let themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/current/editor?context=apps`;
 49→
 50→  try {
 51→    const themeResponse = await admin.graphql(`{
 52→      themes(first: 1, roles: MAIN) {
 53→        nodes {
 54→          id
 55→          name
 56→          files(filenames: ["config/settings_data.json"], first: 1) {
 57→            nodes {
 58→              body {
 59→                ... on OnlineStoreThemeFileBodyText {
 60→                  content
 61→                }
 62→              }
 63→            }
 64→          }
 65→        }
 66→      }
 67→    }`);
 68→    const themeData = (await themeResponse.json()) as {
 69→      data?: {
 70→        themes?: {
 71→          nodes?: Array<{
 72→            id: string;
 73→            name: string;
 74→            files?: {
 75→              nodes?: Array<{
 76→                body?: { content?: string };
 77→              }>;
 78→            };
 79→          }>;
 80→        };
 81→      };
 82→    };
 83→    const mainTheme = themeData?.data?.themes?.nodes?.[0];
 84→    if (mainTheme) {
 85→      // Extract numeric ID from GID (e.g. "gid://shopify/OnlineStoreTheme/123")
 86→      const gidParts = mainTheme.id.split("/");
 87→      const numericId = gidParts[gidParts.length - 1];
 88→      activeThemeName = mainTheme.name;
 89→      themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
 90→      themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;
 91→
 92→      const content = mainTheme.files?.nodes?.[0]?.body?.content;
 93→      if (content) {
 94→        const settingsData = JSON.parse(content) as {
 95→          current?: { blocks?: Record<string, unknown> };
 96→        };
 97→        const blocks = settingsData?.current?.blocks ?? {};
 98→        // Block keys/types in settings_data.json look like:
 99→        // shopify://apps/<handle>/blocks/app_embed/<uuid>
100→        // Only match our app using the SHOPIFY_API_KEY (client_id)
101→        const apiKey = process.env.SHOPIFY_API_KEY ?? "";
102→        appEmbedEnabled = Object.entries(blocks).some(
103→          ([key, block]) => {
104→            const b = block as { type?: string; disabled?: boolean };
105→            const typeStr = b.type ?? "";
106→            const isAppEmbed =
107→              typeStr.includes("app-embed") ||
108→              typeStr.includes("app_embed");
109→            if (!isAppEmbed || b.disabled === true) return false;
110→            if (apiKey && (key.includes(apiKey) || typeStr.includes(apiKey))) {
111→              return true;
112→            }
113→            return false;
114→          },
115→        );
116→      }
117→    }
118→  } catch {
119→    // Non-fatal — embed status defaults to false
120→  }
121→
122→  return {
123→    stats,
124→    subscription,
125→    appEmbedEnabled,
126→    activeThemeName,
127→    themeEditorUrl,
128→    themeEditorAppEmbedsUrl,
129→  };
130→};
