231→
232→                  <BlockStack gap="100">
233→                    <Text as="p" variant="headingXl" fontWeight="bold" tone="success">
234→                      {stats.allowed}
235→                    </Text>
236→                    <Text as="p" variant="bodySm" tone="subdued">
237→                      Serviceable
238→                    </Text>
239→                  </BlockStack>
240→
241→                  <BlockStack gap="100">
242→                    <Text as="p" variant="headingXl" fontWeight="bold" tone={stats.blocked > 0 ? "critical" : "subdued"}>
243→                      {stats.blocked}
244→                    </Text>
