311→
312→          {/* ─── 4. GETTING STARTED ─── */}
313→          {isEmpty && (
314→            <Card>
315→              <BlockStack gap="400">
316→                <Text as="h2" variant="headingMd">
317→                  Get started
318→                </Text>
319→                <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
320→                  {[
321→                    {
322→                      step: "1",
323→                      title: "Add zip codes",
324→                      desc: "Enter the zip codes you deliver to, or import them via CSV.",
