365→                              alignment="center"
366→                              tone="text-inverse"
367→                            >
368→                              {item.step}
369→                            </Text>
370→                          </Box>
371→                          <Text as="h3" variant="headingSm">
372→                            {item.title}
373→                          </Text>
374→                        </InlineStack>
375→                        <Text as="p" variant="bodySm" tone="subdued">
