  }, [isDirty, shopify]);

  // Listen for save bar events
  useEffect(() => {
    const el = document.getElementById("widget-save-bar");
    if (!el) return;
    const onSave = () => handleSave();
    const onDiscard = () => handleDiscard();
    el.addEventListener("save", onSave);
    el.addEventListener("discard", onDiscard);
    return () => {
      el.removeEventListener("save", onSave);
      el.removeEventListener("discard", onDiscard);
    };
  }, [handleSave, handleDiscard]);

  // Dirty-aware setters
  const mark = useCallback(() => setIsDirty(true), []);
  const handlePositionChange = useCallback((v: string) => { setPosition(v); mark(); }, [mark]);
